'use strict';
const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>x==null?'—':(x*100).toFixed(1)+'%';
const fixed=(x,n=3)=>x==null?'—':Number(x).toFixed(n);
const ms=x=>x==null?'—':Math.round(x)+' ms';
const when=x=>new Date(x*1000).toLocaleString('zh-CN',{hour12:false});
const text=x=>typeof x==='string'?x:JSON.stringify(x,null,2);
const typeName={noul:'是 / 否',choice:'选择答案',score:'等级评分'};
const statuses={draft:'待运行',queued:'排队中',running:'运行中',cancelling:'取消中',completed:'已完成',partial_failed:'部分失败',failed:'失败',cancelled:'已取消'};
const previewThresholds=new Map();const appliedThresholds=new Map();
let samplePage=1;
let state=null,route={page:'samples'},selected=new Set(),sampleQuery='',sampleCategory='',sampleType='',taskQuery='',taskStatus='',taskDetail=null,resultTab='results',resultModel='',onlyErrors=false,threshold=.5,analysisModel='',analysisGroup='',resultsFilter='',requestSeq=0;
let editBase=null,editSample=null,editQuestions=[],editQuestionIndex=0,taskSelection=new Set(),loading=false,confirmResolve=null;

function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5000)}
async function api(path,data){const response=await fetch(path,data===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json','X-Control-Token':state?.token||''},body:JSON.stringify(data)});const value=await response.json();if(!response.ok)throw Error(value.error||'操作失败');return value}
function bind(id,event,fn){const el=$(id);if(el)el.addEventListener(event,fn)}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function pill(status){const cls=status==='completed'?'green':['failed','partial_failed'].includes(status)?'red':['running','queued'].includes(status)?'purple':status==='cancelling'?'amber':'';return `<span class="pill ${cls}">${esc(statuses[status]||status)}</span>`}
function parseRoute(){const h=location.hash.slice(1).split('/');return h[0]==='task'&&h[1]?{page:'task',id:h[1]}:{page:h[0]==='tasks'?'tasks':'samples'}}
function setConnection(ok){$('connection').innerHTML=ok?'<i class="local-dot"></i> 已连接':'连接中断 · 请刷新'}

async function refresh(renderPage=true){if(loading)return;loading=true;try{state=await api('/api/state');selected=new Set([...selected].filter(id=>state.samples.some(s=>s.id===id)));$('sample-count').textContent=state.samples.length;$('task-count').textContent=state.tasks.length;setConnection(true);if(renderPage)await renderRoute()}catch(e){setConnection(false);toast(e.message)}finally{loading=false}}
async function renderRoute(){if(!state)return;$('sample-count').textContent=state.samples.length;$('task-count').textContent=state.tasks.length;route=parseRoute();$('nav-samples').classList.toggle('active',route.page==='samples');$('nav-samples').setAttribute('aria-current',route.page==='samples'?'page':'false');$('nav-tasks').setAttribute('aria-current',route.page!=='samples'?'page':'false');$('nav-tasks').classList.toggle('active',route.page!=='samples');$('breadcrumb').textContent='工作空间 / '+(route.page==='samples'?'样本库':route.page==='tasks'?'测试任务':'测试任务 / 任务详情');if(route.page==='samples')renderSamples();else if(route.page==='tasks')renderTasks();else await renderTask();renderTray()}
function navigate(hash){if(location.hash===hash)renderRoute();else location.hash=hash}
function sampleMatches(s){const q=sampleQuery.trim().toLowerCase();return (!q||(s.title+' '+s.id+' '+text(s.case.state)).toLowerCase().includes(q))&&(!sampleCategory||s.category===sampleCategory)&&(!sampleType||Object.values(s.case.questions).some(q=>q.type===sampleType))}
function renderSamples(){const filtered=state.samples.filter(sampleMatches);samplePage=Math.min(samplePage,Math.max(1,Math.ceil(filtered.length/10)));const rows=filtered.slice((samplePage-1)*10,samplePage*10);const categories=[...new Set(state.samples.map(s=>s.category).filter(Boolean))];$('content').innerHTML=`<div class="page-heading"><div><span class="page-eyebrow">测试样本</span><h1>样本库</h1><p class="subtext">维护测试输入和标准答案，选择样本后创建测试任务。</p></div><div class="actions"><button id="import-open">导入样本</button><button id="export-samples">导出</button><button class="primary" id="sample-new">＋ 新增样本</button></div></div>${collectionNav()}<div class="toolbar"><div class="filters"><input class="search" id="sample-search" type="search" placeholder="搜索样本名称或内容" value="${esc(sampleQuery)}" aria-label="搜索样本"><select id="category-filter" aria-label="按分组筛选"><option value="">全部分组</option>${categories.map(c=>`<option ${c===sampleCategory?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="type-filter" aria-label="按类型筛选"><option value="">全部类型</option>${Object.entries(typeName).map(([k,v])=>`<option value="${k}" ${sampleType===k?'selected':''}>${v}</option>`).join('')}</select></div><span class="count-label">${filtered.length} 个样本</span></div><div class="table-wrap"><table class="sample-table"><thead><tr><th class="checkbox-cell"><input type="checkbox" id="select-visible" aria-label="选择全部筛选结果" ${filtered.length&&filtered.every(s=>selected.has(s.id))?'checked':''}></th><th>样本</th><th>类型</th><th>分组</th><th>版本 / 更新时间</th><th style="text-align:right">操作</th></tr></thead><tbody>${rows.map(s=>`<tr><td class="checkbox-cell"><input type="checkbox" data-select="${esc(s.id)}" aria-label="选择 ${esc(s.title)}" ${selected.has(s.id)?'checked':''}></td><td><button class="quiet sample-link" data-inspect="${esc(s.id)}" style="padding:0;text-align:left"><strong>${esc(s.title)}</strong></button><div class="excerpt">${esc(samplePreview(s.case.state))}</div><div class="meta mono">${Object.keys(s.case.questions).length} 个问题</div></td><td><div class="type-tags">${[...new Set(Object.values(s.case.questions).map(q=>q.type))].map(t=>`<span class="pill" data-kind="${t}">${typeName[t]}</span>`).join('')}</div></td><td>${esc(s.category)||'<span class="muted">未分组</span>'}</td><td><span class="mono">v${s.revision}</span><div class="meta">${esc(when(s.updated))}</div></td><td><div class="row-actions"><button class="quiet" data-single="${esc(s.id)}">单样本测试</button><button class="quiet" data-edit="${esc(s.id)}">编辑</button><button class="quiet" data-copy="${esc(s.id)}" aria-label="复制样本" title="复制样本">${copyIcon()}</button><button class="quiet" data-delete="${esc(s.id)}" style="color:var(--muted)" aria-label="移除样本" title="移除样本">${deleteIcon()}</button></div></td></tr>`).join('')}</tbody></table>${!rows.length?`<div class="empty"><span class="empty-symbol">▤</span><h2>${state.samples.length?'没有匹配的样本':'从第一个样本开始'}</h2><p>${state.samples.length?'换一个关键词，或清除筛选条件。':'写下模型要判断的内容，并提供你认可的标准答案。'}</p><button id="empty-new" class="primary">新增样本</button></div>`:''}</div>${samplePagination(filtered.length)}<div class="info-line"><span>ⓘ</span> 样本可以包含多个判断问题。标准答案仅用于评分，不会发送给模型。</div>`;
bindCollection();bind('page-prev','click',()=>{samplePage--;renderSamples()});bind('page-next','click',()=>{samplePage++;renderSamples()});bind('sample-new','click',()=>openSample());bind('empty-new','click',()=>openSample());bind('import-open','click',()=>{$('import-error').textContent='';$('import-dialog').showModal()});bind('export-samples','click',()=>{const list=selected.size?state.samples.filter(s=>selected.has(s.id)):filtered;download('samples.jsonl',list.map(s=>JSON.stringify({...s.case,title:s.title,category:s.category})).join('\n')+'\n','application/x-ndjson')});
bind('sample-search','input',e=>{samplePage=1;sampleQuery=e.target.value;rerenderFocused('sample-search',renderSamples)});bind('category-filter','change',e=>{samplePage=1;sampleCategory=e.target.value;renderSamples()});bind('type-filter','change',e=>{samplePage=1;sampleType=e.target.value;renderSamples()});bind('select-visible','change',e=>{filtered.forEach(s=>e.target.checked?selected.add(s.id):selected.delete(s.id));renderSamples();renderTray()});
document.querySelectorAll('[data-select]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);renderTray();$('select-visible').checked=filtered.length>0&&filtered.every(s=>selected.has(s.id))});
document.querySelectorAll('[data-inspect]').forEach(el=>el.onclick=()=>inspectSample(el.dataset.inspect));document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>openSample(el.dataset.edit));document.querySelectorAll('[data-copy]').forEach(el=>el.onclick=()=>openSample(el.dataset.copy,true));document.querySelectorAll('[data-single]').forEach(el=>el.onclick=()=>openTask([el.dataset.single]));document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>deleteSample(el.dataset.delete));}
function rerenderFocused(id,fn){const el=$(id),pos=el.selectionStart;fn();$(id).focus();try{$(id).setSelectionRange(pos,pos)}catch{}}
function renderTray(){$('selection-tray').hidden=!(route.page==='samples'&&selected.size);if(!$('selection-tray').hidden){$('selection-tray').innerHTML=`<span>已选 <b>${selected.size}</b> 个样本</span><button class="quiet" id="clear-selection">清空选择</button><button class="primary" id="batch-create">创建测试任务 →</button>`;bind('clear-selection','click',()=>{selected.clear();renderSamples();renderTray()});bind('batch-create','click',()=>openTask([...selected]))}}
async function ask(title,message){$('confirm-title').textContent=title;$('confirm-message').textContent=message;$('confirm-dialog').showModal();return new Promise(resolve=>{confirmResolve=resolve})}
async function deleteSample(id){const s=state.samples.find(s=>s.id===id);if(await ask('移除这个样本？',`“${s.title}”将从样本库移除。已有任务保留创建时的样本和结果。`)){try{toast((await api('/api/samples/delete',{id})).message);await refresh()}catch(e){toast(e.message)}}}

function openSample(id=null,copy=false){
 const original=state.samples.find(s=>s.id===id);
 editSample=original&&!copy?structuredClone(original):null;
 editBase=original?structuredClone(original.case):null;
 $('sample-form').reset();$('sample-error').textContent='';
 $('sample-dialog-title').textContent=editSample?'编辑样本':copy?'复制样本':'新增样本';
 $('sample-title').value=original?original.title+(copy?' · 副本':''):'';
 $('sample-category').value=original?.category||'';
 $('sample-id').value=editSample?editSample.id:'sample-'+crypto.randomUUID().slice(0,8);$('sample-id').readOnly=!!editSample;
 const input=editBase?.state??'';const structured=typeof input!=='string';
 $('sample-state').value=structured?JSON.stringify(input,null,2):input;
 $('structured-state').checked=structured;
 $('sample-state-label').hidden=structured;$('sample-structured-editor').hidden=!structured;
 $('sample-structured-editor').innerHTML=structured?P.editor(input):'';
 $('sample-raw-input').value=JSON.stringify(input,null,2);
 editQuestions=editBase?Object.entries(editBase.questions).map(([key,q])=>({key,...q,expected:editBase.expected[key],_title:editBase.presentation?.questions?.[key]?.title||P.questionTitle(original,key)})):[{key:'decision',type:'noul',instructions:'',expected:false,_title:''}];
 editQuestionIndex=0;renderQuestion();$('sample-dialog').showModal();
}

function readQuestion(){
 const q=editQuestions[editQuestionIndex];if(!$('question-title'))return;
 q._title=$('question-title').value.trim();
 q.instructions=typeof q.instructions==='object'?P.readEditor($('instruction-editor'),q.instructions):$('question-instructions').value;
 if(q.type==='choice'){
  const previous=q.criteria||{};q.criteria={};
  document.querySelectorAll('[data-option-label]').forEach(el=>{const key=el.dataset.optionLabel;const value=el.value.trim();if(!value)throw Error('请为每个候选答案填写含义');q.criteria[key]=typeof previous[key]==='object'&&P.plain(previous[key])===value?previous[key]:value});
 }else if(q.type==='score'){
  const previous=q.criteria||[];q.criteria=[...document.querySelectorAll('[data-level-label]')].map((el,i)=>{if(!el.value.trim())throw Error('请填写每个评分等级的含义');return typeof previous[i]==='object'&&P.plain(previous[i])===el.value.trim()?previous[i]:el.value.trim()});
 }
 q.expected=q.type==='noul'?$('question-answer').value==='true':q.type==='score'?Number($('question-answer').value):$('question-answer').value;
}

function renderQuestion(){
 const q=editQuestions[editQuestionIndex];
 $('question-tabs').innerHTML=editQuestions.map((q,i)=>`<button type="button" data-question-tab="${i}" class="${i===editQuestionIndex?'active':''}">${esc(q._title||'问题 '+(i+1))}</button>`).join('');
 let options='';
 if(q.type==='choice')options=Object.entries(q.criteria||{}).map(([key,value])=>`<div class="answer-editor-row"><input data-option-label="${esc(key)}" aria-label="候选答案" value="${esc(P.plain(value))}" required><button type="button" class="quiet" data-remove-option="${esc(key)}" aria-label="移除候选答案">移除</button></div>`).join('');
 if(q.type==='score')options=(q.criteria||[]).map((value,i)=>`<div class="answer-editor-row"><span class="level-number">${i} 分</span><input data-level-label="${i}" aria-label="${i} 分的含义" value="${esc(P.plain(value))}" required></div>`).join('');
 let answers=q.type==='noul'?'<option value="true" '+(q.expected===true?'selected':'')+'>是</option><option value="false" '+(q.expected!==true?'selected':'')+'>否</option>':q.type==='choice'?Object.entries(q.criteria||{}).map(([key,value])=>`<option value="${esc(key)}" ${q.expected===key?'selected':''}>${esc(P.plain(value))}</option>`).join(''):(q.criteria||[]).map((value,i)=>`<option value="${i}" ${q.expected===i?'selected':''}>${esc(P.plain(value))}（${i} 分）</option>`).join('');
 if(q.type==='score'&&Number.isFinite(q.expected)&&!Number.isInteger(q.expected))answers+=`<option value="${q.expected}" selected>${q.expected} 分（当前参考值）</option>`;
 $('question-editor').innerHTML=`<div class="question-box"><div class="form-grid equal"><label>问题名称<input id="question-title" required maxlength="100" placeholder="例如：是否存在未经证实的承诺？" value="${esc(q._title||'')}"></label><label>判断方式<select id="question-type">${Object.entries(typeName).map(([key,title])=>`<option value="${key}" ${q.type===key?'selected':''}>${title}</option>`).join('')}</select></label></div><label>判断标准<span class="hint">写明什么情况下应该选择哪个答案。</span>${typeof q.instructions==='object'?`<div id="instruction-editor" class="structured-form">${P.editor(q.instructions)}</div>`:`<textarea id="question-instructions" required rows="3" placeholder="例如：只有明确说退款已经完成，但记录仍在处理中，才判断为是。">${esc(q.instructions||'')}</textarea>`}</label>${q.type==='noul'?'':`<div class="option-editor"><label>${q.type==='choice'?'候选答案':'评分等级（从低到高）'}</label>${options}<button type="button" class="quiet" id="add-option">＋ ${q.type==='choice'?'添加答案':'添加等级'}</button></div>`}<label>参考答案<select id="question-answer" required>${answers}</select></label>${editQuestions.length>1?'<button type="button" class="quiet text-red" id="remove-question">移除这个问题</button>':''}</div>`;
 document.querySelectorAll('[data-question-tab]').forEach(el=>el.onclick=()=>{try{readQuestion();editQuestionIndex=Number(el.dataset.questionTab);renderQuestion()}catch(e){$('sample-error').textContent=e.message}});
 bind('question-type','change',e=>{q._title=$('question-title').value;q.instructions=typeof q.instructions==='object'?P.readEditor($('instruction-editor'),q.instructions):$('question-instructions').value;q.type=e.target.value;
  if(q.type==='choice'){q.criteria={answer_1:'答案一',answer_2:'答案二'};q.expected='answer_1'}else if(q.type==='score'){q.criteria=['无影响','轻微影响','严重影响'];q.expected=0}else{delete q.criteria;q.expected=false}renderQuestion()});
 bind('add-option','click',()=>{try{readQuestion();if(q.type==='choice'){let i=Object.keys(q.criteria).length+1;while(Object.hasOwn(q.criteria,'answer_'+i))i++;q.criteria['answer_'+i]='新答案'}else q.criteria.push('更高等级');renderQuestion()}catch(e){$('sample-error').textContent=e.message}});
 document.querySelectorAll('[data-remove-option]').forEach(el=>el.onclick=()=>{try{readQuestion();if(Object.keys(q.criteria).length<=2)throw Error('请至少保留两个候选答案');delete q.criteria[el.dataset.removeOption];if(!Object.hasOwn(q.criteria,q.expected))q.expected=Object.keys(q.criteria)[0];renderQuestion()}catch(e){$('sample-error').textContent=e.message}});
 bind('remove-question','click',()=>{editQuestions.splice(editQuestionIndex,1);editQuestionIndex=0;renderQuestion()});
}

async function saveSample(e){
 e.preventDefault();$('sample-error').textContent='';
 try{
  readQuestion();const c=editBase?structuredClone(editBase):{id:$('sample-id').value};c.id=$('sample-id').value.trim();
  c.state=$('structured-state').checked?P.readEditor($('sample-structured-editor'),editBase.state):$('sample-state').value;
  c.questions={};c.expected={};c.presentation={questions:{}};
  for(const question of editQuestions){const {key,expected,_title,...q}=structuredClone(question);if(!key||Object.hasOwn(c.questions,key))throw Error('问题编号重复，请重新添加问题');if(!_title?.trim())throw Error('请为每个问题填写名称');if(q.type==='score'&&(!Number.isFinite(expected)||expected<0||expected>q.criteria.length-1))throw Error('参考评分超出了评分等级');c.questions[key]=q;c.expected[key]=expected;c.presentation.questions[key]={title:_title}}
  const payload={case:c,title:$('sample-title').value.trim(),category:$('sample-category').value.trim()};if(editSample)payload.revision=editSample.revision;
  $('save-sample').disabled=true;const r=await api('/api/samples/save',payload);$('sample-dialog').close();toast(r.message);await refresh();
 }catch(e){$('sample-error').textContent=e.message}finally{$('save-sample').disabled=false}
}

function inspectSample(id){const s=state.samples.find(s=>s.id===id);showSample(s)}
function sampleBody(s){
 return `<section class="human-section"><h3>要测试的内容</h3>${P.content(s.case.state)}</section><section class="human-section"><h3>问题与参考答案</h3>${Object.entries(s.case.questions).map(([key,q])=>`<article class="human-question"><div class="question-summary"><h4>${esc(P.questionTitle(s,key))}</h4><span class="pill">${typeName[q.type]}</span></div><div class="human-answer"><span>参考答案</span><strong>${esc(P.answer(q,s.case.expected[key]))}</strong></div><details class="business-detail"><summary>判断标准${q.criteria?'与候选答案':''}</summary>${P.content(q.instructions||'未单独提供')}${q.criteria?`<ul class="human-options">${Object.entries(q.criteria).map(([option,value])=>`<li>${q.type==='score'?'<span class="level-number">'+option+' 分</span>':''}${esc(P.plain(value))}</li>`).join('')}</ul>`:''}</details></article>`).join('')}</section>${s.case.reference_reason?`<section class="reference-note"><h4>参考标注说明</h4><p>${esc(s.case.reference_reason)}</p>${s.case.source?`<small>${esc(s.case.source)}</small>`:''}</section>`:''}${P.raw(s.case).replace('查看原始输入','查看原始样本数据').replace('<h4>原始输入</h4>','<h4>样本数据（含本地参考答案）</h4>')}`;
}

function showSample(s){$('inspect-title').textContent=s.title;$('inspect-body').innerHTML=sampleBody(s);$('inspect-dialog').showModal()}
function label(v){return v===true?'是':v===false?'否':String(v)}

function openTask(ids=[]){taskSelection=new Set(ids);$('task-form').reset();$('task-error').textContent='';$('new-task-name').value=ids.length===1?'单样本 · '+state.samples.find(s=>s.id===ids[0])?.title:'批量测试 · '+new Date().toLocaleDateString('zh-CN');$('pick-search').value='';renderPicker();$('task-dialog').showModal()}
function renderPicker(){const query=$('pick-search').value.toLowerCase();$('task-sample-picker').innerHTML=state.samples.filter(s=>(s.title+' '+s.category+' '+s.id).toLowerCase().includes(query)).map(s=>`<label class="pick-row"><input type="checkbox" data-pick="${esc(s.id)}" ${taskSelection.has(s.id)?'checked':''}><span>${esc(s.title)}</span><small>${esc(s.category)}</small></label>`).join('')||'<p class="empty" style="padding:15px">没有匹配样本</p>';document.querySelectorAll('[data-pick]').forEach(el=>el.onchange=()=>{el.checked?taskSelection.add(el.dataset.pick):taskSelection.delete(el.dataset.pick);estimate()});estimate()}
function estimate(){const count=$('task-form').querySelectorAll('[name=model]:checked').length;const reps=Number($('new-task-repeats').value);$('task-score-tolerance-label').hidden=!state.samples.some(s=>taskSelection.has(s.id)&&Object.values(s.case.questions).some(q=>q.type==='score'));$('pick-count').textContent='已选 '+taskSelection.size+' 个';$('request-estimate').textContent=`${taskSelection.size===1?'单样本测试':'批量样本测试'} · ${taskSelection.size} 个样本 × ${count} 个模型 × ${reps} 次 = ${taskSelection.size*count*reps} 次模型测试`;}
async function createTask(e){e.preventDefault();$('task-error').textContent='';const buttons=[...$('task-form').querySelectorAll('button[type=submit]')];try{if(!taskSelection.size)throw Error('请至少选择一个样本');const models=[...$('task-form').querySelectorAll('[name=model]:checked')].map(el=>el.value);if(!models.length)throw Error('请至少选择一个模型');buttons.forEach(b=>b.disabled=true);const r=await api('/api/tasks/create',{name:$('new-task-name').value.trim(),sample_ids:[...taskSelection],models,repeats:Number($('new-task-repeats').value),score_tolerance:Number($('task-score-tolerance').value),start:e.submitter?.value==='run'});$('task-dialog').close();selected.clear();toast(r.message);state=await api('/api/state');resultTab='results';threshold=.5;navigate('#task/'+r.id)}catch(e){$('task-error').textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}}

function renderTasks(){const tasks=state.tasks.filter(t=>(!taskQuery||t.name.toLowerCase().includes(taskQuery.toLowerCase()))&&(!taskStatus||t.status===taskStatus));$('content').innerHTML=`<div class="page-heading"><div><span class="page-eyebrow">按需测试</span><h1>测试任务</h1><p class="subtext">为选定样本运行一次测试，每个任务独立保存输入、配置和结果。</p></div><button class="primary" id="task-new">＋ 创建测试任务</button></div>${!state.worker?'<div class="banner">任务执行服务未连接。可以创建任务，请让我检查后台后再运行。</div>':''}<div class="toolbar"><div class="filters"><input class="search" type="search" id="task-search" placeholder="搜索任务名称" value="${esc(taskQuery)}" aria-label="搜索任务"><select id="task-status" aria-label="按状态筛选"><option value="">全部状态</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${taskStatus===k?'selected':''}>${v}</option>`).join('')}</select></div><span class="count-label">${tasks.length} 个任务</span></div><div class="table-wrap"><table class="task-table"><thead><tr><th>任务名称</th><th>状态</th><th>样本 / 模型</th><th>进度</th><th>创建时间</th><th>操作</th></tr></thead><tbody>${tasks.map(t=>`<tr><td><button class="quiet" data-open-task="${esc(t.id)}" style="text-align:left;padding:0"><strong>${esc(t.name)}</strong></button><div class="meta">${t.sample_count===1?'单样本':'批量'}测试 ${t.config.provider==='mock'?' · 离线验证':''}</div></td><td>${pill(t.status)}</td><td>${t.sample_count} 个样本<div class="meta">${t.config.models.map(esc).join(' / ')}</div></td><td><span class="mono">${t.done} / ${t.total}</span><div class="progress"><div style="width:${100*t.done/t.total}%"></div></div></td><td class="muted">${esc(when(t.created))}</td><td><div class="row-actions">${t.status==='draft'?`<button class="quiet" data-task-action="start" data-id="${t.id}">运行</button>`:''}<button class="quiet" data-open-task="${t.id}">查看</button></div></td></tr>`).join('')}</tbody></table>${!tasks.length?`<div class="empty"><span class="empty-symbol">▷</span><h2>${state.tasks.length?'没有匹配的任务':'还没有测试任务'}</h2><p>选一个样本快速试验，或选一批样本比较两个模型。</p><button class="primary" id="empty-task">创建测试任务</button></div>`:''}</div><div class="info-line"><span>ⓘ</span> 没有定时评测。只有你点击运行后，任务才会调用模型。</div>`;bind('task-new','click',()=>openTask());bind('empty-task','click',()=>openTask());bind('task-search','input',e=>{taskQuery=e.target.value;rerenderFocused('task-search',renderTasks)});bind('task-status','change',e=>{taskStatus=e.target.value;renderTasks()});bindTaskActions()}
function bindTaskActions(){document.querySelectorAll('[data-open-task]').forEach(el=>el.onclick=()=>{resultTab='results';threshold=.5;resultModel='';analysisGroup='';navigate('#task/'+el.dataset.openTask)});document.querySelectorAll('[data-task-action]').forEach(el=>el.onclick=()=>taskAction(el.dataset.id,el.dataset.taskAction))}
async function taskAction(id,action){try{if(action==='archive'&&!await ask('移出这个任务？','任务将从列表隐藏，已有结果仍保存在本机。'))return;const r=await api('/api/tasks/action',{id,action});toast(r.message);state=await api('/api/state');if(action==='archive')navigate('#tasks');else if(action==='clone'){resultTab='config';navigate('#task/'+r.id)}else await renderRoute()}catch(e){toast(e.message)}}
async function renderTask(){const seq=++requestSeq;try{const t=await api('/api/task?id='+encodeURIComponent(route.id));if(seq!==requestSeq||parseRoute().id!==t.id)return;taskDetail=t;loadAppliedPolicies(t);const active=['queued','running','cancelling'].includes(t.status);$('content').innerHTML=`<a href="#tasks" class="back">← 返回测试任务</a><div class="page-heading" style="margin-bottom:0"><div><h1>${esc(t.name)}</h1><div class="task-meta">${pill(t.status)}<span>${t.sample_count===1?'单样本':'批量'}测试 · ${t.sample_count} 个样本</span><span>${esc(when(t.created))}</span>${t.config.provider==='mock'?'<span class="pill amber">离线模拟</span>':''}</div></div><div class="actions">${t.status==='draft'?'<button class="primary" data-task-action="start" data-id="'+t.id+'">运行任务</button>':''}${['running','queued'].includes(t.status)?'<button data-task-action="cancel" data-id="'+t.id+'">取消任务</button>':''}${!active?'<button data-task-action="clone" data-id="'+t.id+'">复制为新任务</button><button class="quiet" data-task-action="archive" data-id="'+t.id+'">移出列表</button>':''}<button id="export-task" ${t.done?'':'disabled'}>导出报告</button></div></div>${t.error?`<div class="banner" style="margin-top:20px">${esc(t.error)}</div>`:''}<div class="tabs"><button data-tab="results" class="${resultTab==='results'?'active':''}">测试结果</button><button data-tab="threshold" class="${resultTab==='threshold'?'active':''}">判断阈值</button><button data-tab="config" class="${resultTab==='config'?'active':''}">样本与配置</button></div><div id="task-tab-content"></div>`;bindTaskActions();document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{resultTab=el.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===resultTab));renderTaskTab()});bind('export-task','click',()=>exportHumanReport(t));renderTaskTab()}catch(e){toast(e.message);$('content').innerHTML='<div class="empty">无法读取任务，请返回任务列表重试。</div>'}}
function renderTaskTab(){document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===resultTab));if(resultTab==='config')renderConfig();else if(resultTab==='threshold')renderThreshold();else renderResults()}
function resultRows(){
 const t=taskDetail,samples=new Map(t.samples.map(s=>[s.id,s]));
 return t.results.flatMap((r,index)=>{const s=samples.get(r.case_id);if(r.status!=='ok')return [{...r,sample:s,resultIndex:index,key:'',outcome:'error'}];return r.metrics.map(m=>{
  const a=r.response.answers[m.question],q=s.case.questions[m.question];let pred=m.prediction,correct=m.correct,p=null;
  if(m.type==='noul'){p=Number(a.noul);pred=p>=thresholdFor(r.model,m.question,q,s);correct=Number(pred===m.expected)}else if(m.type==='score')pred=m.score;
  return {...r,sample:s,resultIndex:index,key:m.question,type:m.type,question:q,instructions:q.instructions,criteria:q.criteria,expected:m.expected,prediction:pred,correct,score:m.score,probability:p,mae:m.mae,outcome:m.type==='score'?(m.mae<=(t.config.score_tolerance??.5)?'ok':'wrong'):(correct?'ok':'wrong')};
 })});
}

function renderResults(){
 const t=taskDetail,all=resultRows().filter(r=>!resultModel||r.model===resultModel),valid=all.filter(r=>r.type&&r.type!=='score'),scored=all.filter(r=>r.type==='score');
 const rows=all.filter(r=>(!onlyErrors||r.outcome!=='ok')&&(!resultsFilter||(r.sample.title+' '+(r.key?P.questionTitle(r.sample,r.key):'')).toLowerCase().includes(resultsFilter.toLowerCase())));
 const ok=valid.filter(r=>r.correct).length,errors=all.filter(r=>r.status!=='ok').length;
 $('task-tab-content').innerHTML=`<div class="result-stats"><div><small>测试已完成</small><b>${t.done}<span class="muted" style="font-size:13px"> / ${t.total} 次</span></b></div>${valid.length?`<div><small>判断与参考答案一致</small><b>${pct(ok/valid.length)}</b><small>${ok} / ${valid.length} 次判断</small></div>`:''}${scored.length?`<div><small>平均评分差距</small><b>${fixed(scored.reduce((v,r)=>v+r.mae,0)/scored.length,2)} <span class="unit">分</span></b></div>`:''}<div><small>未成功的测试</small><b class="${errors?'text-red':''}">${errors}</b></div><div class="legend-note">结果按本任务已保存的判断规则展示。拖动阈值只作预览，点击保存后才会更新这里。</div></div>${!t.done?`<div class="panel empty"><span class="empty-symbol">▷</span><h2>${t.status==='draft'?'任务已创建，准备好后运行':'还没有测试结果'}</h2><p>${t.status==='draft'?'点击右上角“运行任务”开始。':t.status==='cancelled'?'任务已取消，可以复制后重新运行。':'正在逐个测试，结果会自动更新。'}</p></div>`:`<div class="toolbar"><div class="filters"><select id="result-model" aria-label="筛选模型"><option value="">全部模型</option>${t.config.models.map(m=>`<option ${m===resultModel?'selected':''}>${esc(m)}</option>`).join('')}</select><input id="result-search" class="search" type="search" placeholder="搜索样本或问题" aria-label="搜索结果" value="${esc(resultsFilter)}"></div><label class="check-inline"><input type="checkbox" id="only-errors" ${onlyErrors?'checked':''}>只看与预期不符或未成功的测试</label></div><div class="table-wrap"><table class="result-table"><thead><tr><th>样本与问题</th><th>模型</th><th>参考答案</th><th>模型的判断</th><th>对比结果</th><th>耗时</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.sample.title)}</strong><div class="meta question-caption">${r.key?esc(P.questionTitle(r.sample,r.key)):''}${t.config.repeats>1?' · 第 '+(r.repeat+1)+' 次':''}</div></td><td>${esc(r.model)}</td><td class="answer-cell">${r.type?esc(P.answer(r.question,r.expected)):'—'}</td><td class="answer-cell">${r.type==='score'?esc(P.scored(r.question,r.score)):r.type?esc(P.answer(r.question,r.prediction)):'未获得判断'}${r.probability!=null?`<div class="prob">认为答案为“是”的倾向：${pct(r.probability)}</div>`:''}</td><td><span class="pill ${r.outcome==='ok'?'green':'red'}">${r.outcome==='error'?'未成功':r.type==='score'?(r.outcome==='ok'?'在允许误差内':'超出允许误差'):(r.correct?'符合预期':'与预期不符')}</span>${r.type==='score'?`<div class="meta">相差 ${fixed(r.mae,2)} 分</div>`:''}</td><td class="muted mono">${ms(r.latency)}</td><td><button class="quiet" data-result="${r.resultIndex}">查看详情</button></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty" style="padding:30px">没有符合筛选条件的结果。</div>':''}</div><div class="info-line"><span>ⓘ</span> ${scored.length?'评分允许误差为 '+(t.config.score_tolerance??.5)+' 分，可在创建任务时设置。':''}未成功的测试不计入质量指标。相同样本的多次测试不是多个独立样本。</div>`}`;
 bind('result-model','change',e=>{resultModel=e.target.value;renderResults()});bind('result-search','input',e=>{resultsFilter=e.target.value;rerenderFocused('result-search',renderResults)});bind('only-errors','change',e=>{onlyErrors=e.target.checked;renderResults()});document.querySelectorAll('[data-result]').forEach(el=>el.onclick=()=>inspectResult(Number(el.dataset.result)));
}

function inspectResult(index){
 const r=taskDetail.results[index],s=taskDetail.samples.find(s=>s.id===r.case_id);$('inspect-title').textContent=s.title+' · '+r.model;
 const evaluated=resultRows().filter(row=>row.resultIndex===index);
 let body=r.status==='ok'?evaluated.map(row=>{const q=row.question,a=r.response.answers[row.key];const probs=q.type==='noul'?[['是',a.noul],['否',1-a.noul]]:Object.entries(a.probabilities).map(([key,value])=>[q.type==='score'?`${P.plain(q.criteria[Number(key)])}（${key} 分）`:P.answer(q,key),value]);return `<article class="human-question"><h3>${esc(P.questionTitle(s,row.key))}</h3><div class="judgement-pair"><div><small>参考答案</small><strong>${esc(P.answer(q,row.expected))}</strong></div><div><small>模型判断</small><strong>${esc(q.type==='score'?P.scored(q,row.score):P.answer(q,row.prediction))}</strong></div></div><p class="outcome-line ${row.outcome==='ok'?'text-green':'text-red'}">${row.outcome==='ok'?'符合本任务的预期':'与本任务的预期不符'}${q.type==='score'?`，相差 ${fixed(row.mae,2)} 分`:''}</p>${q.type==='noul'?`<p class="hint">本问题当前采用 ${pct(thresholdFor(r.model,row.key,q,s))} 的判断阈值。模型倾向达到阈值时判为“是”。</p>`:''}<details class="business-detail"><summary>查看模型对各答案的倾向</summary><p class="hint">这是模型返回的分数，不保证等于真实世界中的正确概率。</p>${probs.map(([title,value])=>`<div class="answer-row"><span>${esc(title)}</span><span class="mono">${pct(value)}<div class="bar"><div style="width:${100*value}%"></div></div></span></div>`).join('')}</details></article>`}).join(''):'<div class="banner">本次没有获得判断，请检查账户推理权限或网络后重试。</div>';
 body+=`<section class="human-section"><h3>本次测试的内容</h3>${P.content(s.case.state)}</section>`;
 if(s.case.reference_reason)body+=`<div class="reference-note"><h4>参考标注说明</h4><p>${esc(s.case.reference_reason)}</p></div>`;
 const input={model:r.model,...Object.fromEntries(['state','questions','images','videos','audio'].filter(key=>key in s.case).map(key=>[key,s.case[key]]))};
 $('inspect-body').innerHTML=body+P.raw(input,r.response||{error:r.error_type});$('inspect-dialog').showModal();
}

function binaryGroups(){
 const groups=new Map();for(const r of resultRows().filter(r=>r.type==='noul')){
  const id=r.sample.question_rules[r.key];if(!groups.has(id))groups.set(id,{key:id,id:r.key,title:P.questionTitle(r.sample,r.key),rows:[]});groups.get(id).rows.push(r);
 }return [...groups.values()].sort((a,b)=>new Set(b.rows.map(r=>r.case_id)).size-new Set(a.rows.map(r=>r.case_id)).size);
}

function thresholdFor(model,key,q,sample){const rule=sample?.question_rules?.[key];return appliedThresholds.get(taskDetail.id+'|'+model+'|'+rule)??.5}

function binaryStats(rows,t){let tp=0,tn=0,fp=0,fn=0,brier=0;for(const r of rows){const yes=r.probability>=t;const gold=r.expected;if(yes&&gold)tp++;else if(yes)fp++;else if(gold)fn++;else tn++;brier+=(r.probability-Number(gold))**2}return {tp,tn,fp,fn,precision:tp+fp?tp/(tp+fp):null,recall:tp+fn?tp/(tp+fn):null,f1:2*tp+fp+fn?2*tp/(2*tp+fp+fn):null,brier:rows.length?brier/rows.length:null}}
function renderThreshold(){
 const groups=binaryGroups();if(!groups.length){$('task-tab-content').innerHTML='<div class="panel empty"><h2>这个任务不需要“是／否”判断阈值</h2><p>选择题直接比较候选答案；评分题按等级计算分数。只有“是／否”问题才需要设置此阈值。</p></div>';return}
 if(!groups.some(g=>g.key===analysisGroup))analysisGroup=groups[0].key;
 if(!taskDetail.config.models.includes(analysisModel))analysisModel=taskDetail.config.models[0];
 const scope=taskDetail.id+'|'+analysisModel+'|'+analysisGroup;
 const saved=appliedThresholds.get(scope)??.5;threshold=previewThresholds.get(scope)??saved;
 $('task-tab-content').innerHTML=`<section class="panel"><div class="threshold-title"><div><h2>什么时候判断为“是”？</h2><p class="subtext">模型先给出一个倾向分数，你再决定多高才算“是”。这不会改变模型或重新发起测试。</p></div><span class="pill">当前任务内生效</span></div><div class="threshold-controls"><label>要分析的问题<select id="analysis-question">${groups.map((g,i)=>`<option value="${i}" ${g.key===analysisGroup?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><label>模型<select id="analysis-model">${taskDetail.config.models.map(m=>`<option ${m===analysisModel?'selected':''}>${esc(m)}</option>`).join('')}</select></label></div><div class="threshold-help"><b>调低阈值</b>更容易判为“是”，通常会减少漏报、增加误报。<br><b>调高阈值</b>更谨慎地判为“是”，通常会减少误报、增加漏报。</div><div class="slider-label"><label for="threshold-slider">预览判断阈值</label><div class="threshold-number"><input id="threshold-percent" type="number" min="0" max="100" step="0.01" value="${Number((threshold*100).toFixed(2))}" aria-label="阈值百分比"><span>%</span><output id="threshold-value" class="sr-only">${fixed(threshold,4)}</output></div></div><input type="range" id="threshold-slider" min="0" max="1" step="0.0001" value="${threshold}" style="--range-fill:${threshold*100}%" aria-label="决策阈值"><div class="slider-scale"><span>更容易判为“是”</span><button class="quiet" id="threshold-reset">恢复默认 50%</button><span>更谨慎地判为“是”</span></div><div class="policy-actions"><span id="policy-status" class="hint"></span><button id="save-policy" class="primary">保存到此任务</button></div><p class="hint">分数等于阈值时也判为“是”。此设置仅适用于当前模型和当前问题，不影响其他问题。</p></section><div id="analysis-content"></div>`;
 bind('analysis-question','change',e=>{analysisGroup=groups[Number(e.target.value)].key;renderThreshold()});bind('analysis-model','change',e=>{analysisModel=e.target.value;renderThreshold()});
 const preview=value=>{threshold=value;previewThresholds.set(scope,value);$('threshold-value').textContent=fixed(value,4);$('threshold-slider').value=value;$('threshold-slider').style.setProperty('--range-fill',value*100+'%');$('threshold-percent').value=Number((value*100).toFixed(2));updateAnalysis()};
 bind('threshold-slider','input',e=>preview(Number(e.target.value)));
 bind('threshold-percent','input',e=>{if(e.target.value!==''&&e.target.validity.valid)preview(Number(e.target.value)/100)});
 bind('threshold-reset','click',()=>preview(.5));
 bind('save-policy','click',async()=>{try{if(!$('threshold-percent').checkValidity()||$('threshold-percent').value==='')throw Error('请输入 0–100 之间的百分比');$('save-policy').disabled=true;const response=await api('/api/tasks/policy',{id:taskDetail.id,model:analysisModel,rule_id:analysisGroup,threshold});appliedThresholds.set(scope,threshold);taskDetail.decision_policy=taskDetail.decision_policy.filter(p=>p.model!==analysisModel||p.rule_id!==analysisGroup);taskDetail.decision_policy.push({model:analysisModel,rule_id:analysisGroup,threshold});toast(response.message);updateAnalysis()}catch(e){toast(e.message);$('save-policy').disabled=false}});
 updateAnalysis();
}

function curveSvg(rows){
 const levels=[...new Set([0,1,threshold,...rows.map(r=>r.probability),...rows.filter(r=>r.probability<1).map(r=>Math.min(1,r.probability+.000001))])].sort((a,b)=>a-b),points=levels.map(t=>({t,...binaryStats(rows,t)}));const x=t=>36+t*390,y=v=>174-v*146;
 const path=key=>{let line='',connected=false;for(const point of points){if(point[key]==null){connected=false;continue}line+=(connected?'L':'M')+x(point.t)+','+y(point[key]);connected=true}return line};
 return `<svg class="chart" viewBox="0 0 450 210" role="img" aria-label="不同阈值下的精确率和召回率">${[0,.5,1].map(v=>`<line class="grid" x1="36" x2="426" y1="${y(v)}" y2="${y(v)}"/><text x="8" y="${y(v)+4}">${v*100}%</text>`).join('')}<path d="${path('precision')}" fill="none" stroke="#315efb" stroke-width="2"/><path d="${path('recall')}" fill="none" stroke="#187a66" stroke-width="2"/><line x1="${x(threshold)}" x2="${x(threshold)}" y1="25" y2="174" stroke="#b13e56" stroke-dasharray="4 4"/>${[0,.25,.5,.75,1].map(t=>`<text x="${x(t)}" y="196" text-anchor="middle">${t*100}%</text>`).join('')}</svg>`;
}

function distributionSvg(rows){const x=p=>36+p*390;const lines=[{gold:true,y:58,label:'实际为是',color:'#315efb'},{gold:false,y:121,label:'实际为否',color:'#187a66'}];return `<svg class="chart" viewBox="0 0 450 180" role="img" aria-label="实际正负样本的概率分布"><rect x="${x(threshold)}" y="22" width="${390*(1-threshold)}" height="125" fill="#f0f4ff"/>${lines.map(({gold,y,label,color})=>`<line class="grid" x1="36" x2="426" y1="${y}" y2="${y}"/><text x="36" y="${y-23}">${label}</text>${rows.filter(r=>r.expected===gold).map((r,i)=>`<circle cx="${x(r.probability)}" cy="${y+(i%5-2)*4}" r="4" fill="${color}" fill-opacity=".7"><title>${esc(r.sample.title)}: ${fixed(r.probability,4)}</title></circle>`).join('')}`).join('')}<line x1="${x(threshold)}" x2="${x(threshold)}" y1="22" y2="147" stroke="#b13e56" stroke-dasharray="4 4"/>${[0,.25,.5,.75,1].map(p=>`<text x="${x(p)}" y="169" text-anchor="middle">${p.toFixed(2)}</text>`).join('')}</svg>`}
function updateAnalysis(){
 const group=binaryGroups().find(g=>g.key===analysisGroup);const observations=(group?.rows||[]).filter(r=>r.model===analysisModel),rows=independentBinaryRows(observations);
 const saved=appliedThresholds.get(taskDetail.id+'|'+analysisModel+'|'+analysisGroup)??.5,changed=Math.abs(saved-threshold)>1e-9;
 $('policy-status').textContent=changed?`尚未保存 · 当前结果页仍采用 ${pct(saved)}`:`已采用 ${pct(saved)} · 刷新页面后仍保留`;$('save-policy').disabled=!changed;
 if(!rows.length){$('analysis-content').innerHTML='<div class="panel empty">这个模型还没有该问题的有效结果。</div>';return}
 const stats=binaryStats(rows,threshold),positives=rows.filter(r=>r.expected).length,sufficient=positives>0&&positives<rows.length;
 const summary=`<div class="preview-counts"><div><span>预览判为“是”</span><b>${stats.tp+stats.fp} <small>个样本</small></b></div><div><span>其中误报</span><b>${stats.fp}</b><small>实际为否，却判为是</small></div><div><span>漏掉的正例</span><b>${stats.fn}</b><small>实际为是，却判为否</small></div></div>`;
 $('analysis-content').innerHTML=`<section class="panel"><h3>${esc(analysisModel)} · 这批样本会怎样判断</h3><p class="hint">分析问题：${esc(group.title)} 比较 ${rows.length} 个独立样本${observations.length!==rows.length?'，每个样本的重复测试取平均分数':''}。</p>${summary}${!sufficient?`<div class="callout">目前只有${positives===0?'参考答案为“否”':'参考答案为“是”'}的样本，无法同时评估误报和漏报的权衡。可以预览单样本的判断；请加入另一类样本后，再比较统计指标。</div>`:`<div class="metrics"><div class="metric"><small>精确率</small><b>${pct(stats.precision)}</b><small>判为是的样本中，有多少确实为是</small></div><div class="metric"><small>召回率</small><b>${pct(stats.recall)}</b><small>实际为是的样本中，找到了多少</small></div><div class="metric"><small>F1</small><b>${fixed(stats.f1)}</b><small>同时考虑精确率和召回率</small></div></div>`}<p class="hint">${positives} 个参考答案为是，${rows.length-positives} 个为否。预览只使用已保存的分数，不会产生新的模型请求。</p></section>${sufficient?`<details class="business-detail analysis-details"><summary>查看阈值曲线、概率分布和统计明细</summary><div class="analysis-grid"><section class="panel"><h3>精确率与召回率随阈值变化</h3>${curveSvg(rows)}<div class="chart-key"><span><i style="background:#315efb"></i>精确率</span><span><i style="background:#187a66"></i>召回率</span><span><i style="background:#b13e56"></i>预览阈值</span></div></section><section class="panel"><h3>模型给“是”的倾向分布</h3>${distributionSvg(rows)}<p class="hint">虚线右侧会判为“是”。一个点代表一个独立样本。</p></section></div><div class="panel"><h3>统计明细</h3><p>正确识别 ${stats.tp} · 正确排除 ${stats.tn} · 误报 ${stats.fp} · 漏报 ${stats.fn}</p><p class="hint">概率误差（Brier）：${fixed(stats.brier)}，范围 0–1，越低越好；它同时受区分能力和概率校准影响，并非纯校准指标。分母为零的指标显示 —。</p></div></details>`:''}<div class="callout">这是在当前样本上探索判断规则，不是独立验证成绩。请根据误报与漏报的业务代价选择阈值，再用另一批未参与调整的样本验证；不要直接把当前最高 F1 当成最优设置。模型分数也不保证已经校准成真实概率。</div><details class="business-detail"><summary>查看判断阈值的依据</summary><p>默认 50% 只是起点。不同模型与不同问题可以有不同的适用阈值；选择题与评分题使用各自的答案规则。</p><p><a href="https://developers.cloudflare.com/workers-ai/models/clef/" target="_blank" rel="noopener">Cloudflare 模型接口</a> · <a href="https://docs.typesafe.ai/primitives/noul" target="_blank" rel="noopener">Jev 的是／否问题</a> · <a href="https://scikit-learn.org/stable/modules/classification_threshold.html" target="_blank" rel="noopener">阈值选择与独立验证</a></p></details>`;
}

function renderConfig(){
 const t=taskDetail,policies=t.decision_policy||[];
 $('task-tab-content').innerHTML=`<section class="panel"><h3>这次测试怎么做</h3><dl class="config-list"><dt>参与比较的模型</dt><dd>${t.config.models.map(esc).join('、')}</dd><dt>样本数量</dt><dd>${t.sample_count} 个</dd><dt>每个样本测试</dt><dd>每个模型 ${t.config.repeats} 次</dd><dt>预计比较次数</dt><dd>${t.total} 次</dd><dt>评分允许误差</dt><dd>${t.config.score_tolerance??.5} 分（仅评分题）</dd><dt>是／否判断</dt><dd>${policies.length?'已有 '+policies.length+' 条自定义规则，其余使用 50%':'使用默认 50% 阈值'}</dd></dl></section><section class="panel"><h3>本次测试使用的样本</h3><p class="hint">下面是任务创建时保存的内容。之后修改样本库，不会改变本次测试。</p><div class="snapshot-list">${t.samples.map((s,i)=>`<article><div><strong>${esc(s.title)}</strong><p class="hint">${Object.keys(s.case.questions).length} 个问题 · ${esc(s.category||'未分组')}</p></div><button class="quiet" data-snapshot="${i}">查看内容</button></article>`).join('')}</div></section>${P.raw({task_id:t.id,settings:t.config,decision_policy:policies,samples:t.samples},t.results)}<button class="quiet" id="export-raw-task">下载原始测试数据</button>`;
 document.querySelectorAll('[data-snapshot]').forEach(el=>el.onclick=()=>showSample(t.samples[Number(el.dataset.snapshot)]));bind('export-raw-task','click',()=>download(t.id+'.json',JSON.stringify(t,null,2)));
}

document.querySelectorAll('.close-dialog').forEach(el=>el.onclick=()=>el.closest('dialog').close());bind('confirm-no','click',()=>{$('confirm-dialog').close();confirmResolve?.(false);confirmResolve=null});bind('confirm-yes','click',()=>{$('confirm-dialog').close();confirmResolve?.(true);confirmResolve=null});bind('confirm-dialog','cancel',()=>{confirmResolve?.(false);confirmResolve=null});bind('sample-form','submit',saveSample);bind('add-question','click',()=>{try{readQuestion();if(editQuestions.length>=64)throw Error('最多 64 个问题');editQuestions.push({key:'question_'+crypto.randomUUID().slice(0,8),type:'noul',instructions:'',expected:false,_title:''});editQuestionIndex=editQuestions.length-1;renderQuestion()}catch(e){$('sample-error').textContent=e.message}});bind('task-form','submit',createTask);bind('pick-search','input',renderPicker);bind('pick-all','click',()=>{if(taskSelection.size===state.samples.length)taskSelection.clear();else taskSelection=new Set(state.samples.map(s=>s.id));renderPicker()});$('task-form').querySelectorAll('[name=model]').forEach(el=>el.onchange=estimate);bind('new-task-repeats','change',estimate);bind('import-file','change',async e=>{const file=e.target.files[0];if(file){if(file.size>4*1024*1024){$('import-error').textContent='文件超过 4 MB';return}$('import-text').value=await file.text()}});bind('import-form','submit',async e=>{e.preventDefault();$('import-error').textContent='';try{const source=$('import-text').value.trim();if(!source)throw Error('请选择文件或粘贴样本内容');const rows=source.startsWith('[')?JSON.parse(source):source.split('\n').filter(s=>s.trim()).map(s=>JSON.parse(s));const r=await api('/api/samples/import',{samples:rows});$('import-dialog').close();$('import-form').reset();toast(r.message);await refresh()}catch(e){$('import-error').textContent=e.message}});
window.addEventListener('hashchange',()=>{taskDetail=null;resultTab='results';resultModel='';analysisGroup='';threshold=.5;renderRoute()});
refresh();setInterval(async()=>{if(document.querySelector('dialog[open]'))return;const r=parseRoute();if(r.page==='task'&&taskDetail&&!['queued','running','cancelling'].includes(taskDetail.status))return;await refresh(r.page==='tasks'||r.page==='task')},3000);


// Visual workspace helpers. No network calls or evaluation actions.
function samplePreview(value){
 if(typeof value==='string')return value.replace(/\s+/g,' ').slice(0,160);
 if(value&&typeof value==='object'&&!Array.isArray(value)){
  const names={customer:'客户',assistant:'客服',request:'请求',facts:'事实',environment:'环境',primary_checkout:'主购买通道',alternative:'替代通道',log:'日志',order:'订单',refund:'退款编号',amount:'金额',payment_incident_history:'故障记录',business_status:'退款状态'};
  const keys=Object.keys(names).filter(k=>Object.hasOwn(value,k));
  if(keys.length)return keys.map(k=>names[k]+'：'+text(value[k])).join(' · ').replace(/\s+/g,' ').slice(0,180);
  const labels={identity_verified:'已验证身份',days_since_delivery:'签收天数',unused:'商品未使用',digital:'数字商品',production_payment_outage:'当前支付故障',affected_customers:'受影响客户'};
  return Object.entries(value).slice(0,4).map(([k,v])=>(labels[k]||k)+'：'+(typeof v==='boolean'?(v?'是':'否'):text(v))).join(' · ').slice(0,180);
 }
 return text(value).slice(0,160);
}
function collectionNav(){
 const groups=new Map();for(const s of state.samples)groups.set(s.category,(groups.get(s.category)||0)+1);
 return `<div class="collection-nav" role="group" aria-label="样本分组"><button data-collection="" class="${!sampleCategory?'active':''}" aria-pressed="${!sampleCategory}">全部样本 <b>${state.samples.length}</b></button>${[...groups].map(([name,count])=>`<button data-collection="${esc(name)}" class="${sampleCategory===name?'active':''}" aria-pressed="${sampleCategory===name}"><span class="collection-dot"></span>${esc(name.replace('挑战样本 · ',''))||'未分组'} <b>${count}</b></button>`).join('')}</div>`;
}
function bindCollection(){document.querySelectorAll('[data-collection]').forEach(el=>el.onclick=()=>{samplePage=1;sampleCategory=el.dataset.collection;renderSamples();renderTray()})}
function samplePagination(total){const pages=Math.max(1,Math.ceil(total/10));return `<div class="pagination"><span>${total?`显示 ${(samplePage-1)*10+1}–${Math.min(samplePage*10,total)}，共 ${total} 个样本`:'暂无样本'}</span><div class="page-controls"><button id="page-prev" ${samplePage===1?'disabled':''} aria-label="上一页样本">← 上一页</button><span class="page-number">${samplePage} / ${pages}</span><button id="page-next" ${samplePage===pages?'disabled':''} aria-label="下一页样本">下一页 →</button></div></div>`}
function copyIcon(){return '<svg class="svg-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></svg>'}
function deleteIcon(){return '<svg class="svg-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6"/></svg>'}
function focusSearch(){const input=$('sample-search')||$('task-search');if(input){input.focus();input.select()}else{navigate('#samples');setTimeout(()=>$('sample-search')?.focus(),150)}}
bind('global-search','click',focusSearch);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!document.querySelector('dialog[open]')&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();focusSearch()}});
document.addEventListener('input',e=>{if(e.target.id==='threshold-slider')e.target.style.setProperty('--range-fill',Number(e.target.value)*100+'%')});

function loadAppliedPolicies(task){for(const key of appliedThresholds.keys())if(key.startsWith(task.id+'|'))appliedThresholds.delete(key);for(const policy of task.decision_policy||[])appliedThresholds.set(task.id+'|'+policy.model+'|'+policy.rule_id,policy.threshold)}
function independentBinaryRows(observations){const grouped=new Map();for(const row of observations){if(!grouped.has(row.case_id))grouped.set(row.case_id,{...row,probability:0,count:0});const item=grouped.get(row.case_id);item.probability+=row.probability;item.count++}return [...grouped.values()].map(row=>({...row,probability:row.probability/row.count}))}
function exportHumanReport(task){const rows=[['样本','问题','模型','参考答案','模型判断','对比结果','判断阈值','认为答案为是的倾向','评分差距','耗时（毫秒）']];for(const r of resultRows()){rows.push([r.sample.title,r.key?P.questionTitle(r.sample,r.key):'',r.model,r.type?P.answer(r.question,r.expected):'',r.type==='score'?P.scored(r.question,r.score):r.type?P.answer(r.question,r.prediction):'',r.outcome==='error'?'未成功':r.outcome==='ok'?'符合预期':'与预期不符',r.type==='noul'?pct(thresholdFor(r.model,r.key,r.question,r.sample)):'',r.probability==null?'':pct(r.probability),r.mae==null?'':fixed(r.mae,4),Math.round(r.latency)])}download(task.name+'.csv',P.csv(rows),'text/csv;charset=utf-8')}
function syncRawSample(){try{readQuestion();const input=$('structured-state').checked?P.readEditor($('sample-structured-editor'),editBase.state):$('sample-state').value;$('sample-raw-input').value=JSON.stringify(input,null,2);$('sample-raw-question').textContent=JSON.stringify(editQuestions.map(({key,expected,_title,...question})=>({key,question,expected})),null,2)}catch(e){$('sample-error').textContent=e.message}}

bind('sample-raw-detail','toggle',e=>{if(e.target.open)syncRawSample()});
document.addEventListener('input',e=>{
 const el=e.target,select=$('question-answer');if(!select)return;
 const key=el.dataset.optionLabel??el.dataset.levelLabel;if(key==null)return;
 const option=[...select.options].find(option=>option.value===key);
 if(option)option.textContent=(el.value.trim()||'未命名答案')+(el.dataset.levelLabel!=null?'（'+key+' 分）':'');
});
